import{_ as s,o as t,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Raccourcis personnalisés de barre latérale","description":"Créer des liens UIX vers des pages Home Assistant et des sites web.","frontmatter":{"title":"Raccourcis personnalisés de barre latérale","description":"Créer des liens UIX vers des pages Home Assistant et des sites web."},"headers":[],"relativePath":"fr/projects/uix/extras/custom-sidebar-panels.md","filePath":"fr/projects/uix/extras/custom-sidebar-panels.md","lastUpdated":1794475309000}'),n={name:"fr/projects/uix/extras/custom-sidebar-panels.md"};function o(i,e,c,l,u,d){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="raccourcis-personnalises-de-barre-laterale" tabindex="-1">Raccourcis personnalisés de barre latérale <a class="header-anchor" href="#raccourcis-personnalises-de-barre-laterale" aria-label="Permalink to &quot;Raccourcis personnalisés de barre latérale&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">UIX 9.0.0</p><p>Les raccourcis internes et externes font partie de la version stable <strong>9.0.0</strong> et nécessitent <strong>Home Assistant 2026.11.0 ou ultérieur</strong>. La nouvelle restriction aux navigateurs de bureau décrite ci-dessous provient de l’aperçu <strong>9.1.0-beta.1</strong> sur <code>dev</code>.</p></div><p>UIX peut ajouter des entrées à la barre latérale de Home Assistant pour ouvrir une autre page Home Assistant ou un site web. Cela facilite l’accès aux pages fréquemment utilisées sous les paramètres et aux services web associés.</p><p>Ouvrez <strong>Paramètres → Appareils et services → UI eXtension → Configurer</strong>, puis sélectionnez <strong>Manage custom sidebar panels</strong>. Choisissez l’icône et saisissez le titre et la destination.</p><p>Activez <strong>Admin required</strong> pour réserver l’entrée aux comptes administrateurs.</p><p>La destination peut être un chemin Home Assistant commençant par <code>/</code>, comme <code>/config/dashboard</code>, ou une URL absolue <code>http</code> ou <code>https</code>. Les autres schémas d’URL ne sont pas acceptés.</p><p>Activez <strong>Open in new tab (desktop only)</strong> pour ouvrir un chemin interne Home Assistant dans un nouvel onglet d’un navigateur de bureau. L’onglet Home Assistant courant revient à la page précédemment affichée. Dans l’application Companion, UIX navigue plutôt vers le chemin HA à l’intérieur de l’application. Cette option ne s’applique pas aux URL de sites web externes, qui ne peuvent pas s’ouvrir à l’intérieur de l’application Companion.</p><div class="info custom-block"><p class="custom-block-title">Nouvel onglet et blocage des fenêtres surgissantes</p><p>L’ouverture d’un chemin interne HA dans un nouvel onglet dépend de la politique du navigateur de bureau concernant les fenêtres surgissantes. UIX tente de l’ouvrir lors de la sélection du panneau, sans pouvoir le garantir. En cas de blocage, le chemin HA s’ouvre dans l’onglet courant.</p></div><p>Chaque panneau possède une URL interne stable gérée par UIX. Vous pouvez donc modifier son titre, son icône et sa destination sans le recréer. Sa suppression retire immédiatement l’entrée de la barre latérale.</p><div class="tip custom-block"><p class="custom-block-title">Ordre de la barre latérale</p><p>Chaque utilisateur peut <a href="https://www.home-assistant.io/dashboards/dashboards/#reorganizing-items-in-the-sidebar" target="_blank" rel="noreferrer">réorganiser et masquer les entrées</a> depuis son profil.</p></div><div class="info custom-block"><p class="custom-block-title">Redirection</p><p>Un panneau personnalisé est une redirection, pas une copie de la page ni un iframe. Pour une destination interne, UIX remplace l’URL du panneau par la destination configurée afin de ne pas ajouter d’étape de redirection à l’historique du navigateur.</p></div><p>Source : <a href="https://uix.lf.technology/extras/custom-sidebar-panels/" target="_blank" rel="noreferrer">documentation originale anglaise UIX</a>, Lint-Free-Technology/uix, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>.</p><p>Revue complémentaire des sources du 7 novembre 2026 : <a href="https://github.com/Lint-Free-Technology/uix/commit/e7b5bdd811a53960e9559c53a354c7855c537286" target="_blank" rel="noreferrer"><code>dev e7b5bdd</code></a>, incluant <a href="https://github.com/Lint-Free-Technology/uix/commit/1d53592b241ec8666b34d67056671bb37d1c2a1f" target="_blank" rel="noreferrer"><code>1d53592</code></a>. L’indication d’aperçu ne constitue pas une publication stable.</p>',13)])])}const b=s(n,[["render",o]]);export{m as __pageData,b as default};
